// Read-only base data, generated by `npm run build-data`.
// (data/answer_key.json is deliberately NOT exported here — it is for /evals only.)
import accountsJson from "@/data/accounts.json";
import documentsJson from "@/data/documents.json";
import type { Account, DocumentRecord } from "./types";

export const accounts = accountsJson as Account[];
export const documents = documentsJson as DocumentRecord[];

export function getAccount(leadId: string): Account | undefined {
  return accounts.find((a) => a.lead_id === leadId);
}

export function documentsFor(leadId: string): DocumentRecord[] {
  return documents
    .filter((d) => d.linked_lead_ids.includes(leadId))
    .sort((a, b) => b.date.localeCompare(a.date));
}
